    x=by[k]; n=new[k]
    out.append(dict(key=k,title=x['title'],model=n['model'],barKey=x['barKey'],role=x['role'],mandatory=x['mandatory'],requiredScope=x['requiredScope'],evidencePlane=x['evidencePlane'],requiredTestLayers=n.get('layers',x['requiredTestLayers']),passRatings=x['passRatings'],driftMarkers=n['marks'],verification=dict(method=n['method'],check=dict(kind='tests',files=n['files']))))
